{
  "database": {
    "engine": "SQLite (Cloudflare D1)",
    "competitions": {
      "AFLW": {
        "name": "AFL Women's",
        "years": "2017 to current season",
        "coverage": {
          "matches": true,
          "stats": true,
          "lineups": "2022-S7+",
          "pav": "2017+"
        }
      }
    },
    "coverage_contract": {
      "version": 4,
      "season_selectors": {
        "ordinary": "YYYY",
        "AFLW_2022": [
          "2022-S6",
          "2022-S7"
        ],
        "ambiguous": "AFLW 2022 requests are rejected; competition and exact season key are required"
      },
      "review_date": "2026-10-04",
      "how_to_read": "Each table declares a default: `range` (inclusive season span; 'current' = latest season), `expected` (complete | partial | best-effort | absent | not-applicable), and `source`. The default applies to every column of that table. `columns` lists ONLY exceptions — a column appears there when its `expected` or `range` deviates from the table default; any column not listed has exactly the default coverage.",
      "coaching_contract": {
        "by_competition": {
          "AFLM": {
            "range": "1990..current",
            "expected": "partial",
            "source": [
              "afl-tables",
              "footywire comparison"
            ],
            "unit": "participant assignments",
            "notes": [
              "AFL Tables controls canonical assignments. FootyWire observations are comparison evidence only.",
              "Expected assignments equal two per completed match, including Opening Round and finals. Missing rows remain unknown."
            ]
          },
          "AFLW": {
            "range": "all",
            "expected": "not-applicable",
            "source": []
          },
          "VFL": {
            "range": "all",
            "expected": "not-applicable",
            "source": []
          },
          "VFLW": {
            "range": "all",
            "expected": "not-applicable",
            "source": []
          }
        }
      },
      "by_competition": {
        "AFLW": {
          "competitions": {
            "range": "all",
            "expected": "complete",
            "source": [
              "afl-api"
            ]
          },
          "player_provider_ids": {
            "range": "all",
            "expected": "partial",
            "source": [
              "afl-api"
            ]
          },
          "player_id_redirects": {
            "range": "all",
            "expected": "partial",
            "source": [
              "afl-api"
            ]
          },
          "seasons": {
            "range": "all",
            "expected": "complete",
            "source": [
              "afl-api"
            ]
          },
          "season_provider_ids": {
            "range": "all",
            "expected": "partial",
            "source": [
              "afl-api"
            ]
          },
          "teams": {
            "range": "all",
            "expected": "complete",
            "source": [
              "afl-api"
            ]
          },
          "venues": {
            "range": "all",
            "expected": "complete",
            "source": [
              "afl-api",
              "venue-geodata"
            ],
            "columns": {
              "latitude": {
                "expected": "partial"
              },
              "longitude": {
                "expected": "partial"
              },
              "timezone": {
                "expected": "partial"
              },
              "roof": {
                "expected": "partial"
              }
            }
          },
          "players": {
            "range": "all",
            "expected": "partial",
            "source": [
              "mixed-provider and unverified legacy metadata"
            ],
            "columns": {
              "id": {
                "expected": "complete"
              },
              "surname": {
                "expected": "complete"
              },
              "is_retired": {
                "expected": "best-effort"
              }
            }
          },
          "coaches": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "coach_external_ids": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "coach_external_match_ids": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "coach_observations": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "match_coaches": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "public_input_revision": {
            "range": "all",
            "expected": "not-applicable",
            "source": [
              "afl-tables"
            ]
          },
          "matches": {
            "range": "2017..current",
            "expected": "partial",
            "source": [
              "afl-api"
            ],
            "columns": {
              "local_time": {
                "expected": "complete"
              },
              "status": {
                "expected": "complete"
              },
              "kickoff_at": {
                "range": "2026..current"
              },
              "lineups_observed_at": {
                "range": "2026..current"
              }
            }
          },
          "player_match_stats": {
            "range": "2017..current",
            "expected": "partial",
            "source": [
              "afl-api"
            ],
            "columns": {
              "brownlow_votes": {
                "expected": "not-applicable"
              },
              "supercoach_score": {
                "expected": "absent"
              },
              "subbed": {
                "expected": "absent"
              }
            }
          },
          "player_season_pav": {
            "range": "2017..current",
            "expected": "partial",
            "source": [
              "derived-pav"
            ],
            "notes": [
              "Missing required season inputs leave derived values unknown; cancelled and live matches are excluded."
            ]
          },
          "match_lineups": {
            "range": "2022-S7..current",
            "expected": "partial",
            "source": [
              "afl-api"
            ],
            "notes": [
              "Season-seven rosters require exact agreement with recorded player-team appearances; earlier announced teams remain excluded."
            ]
          },
          "match_weather": {
            "range": "2017..current",
            "expected": "partial",
            "source": [
              "open-meteo"
            ]
          },
          "match_predictions": {
            "range": "2026..current",
            "expected": "partial",
            "source": [
              "tipper"
            ],
            "notes": [
              "Retained historical backfill and real-time predictions; missing rows remain possible."
            ]
          }
        }
      }
    },
    "tables": {
      "competitions": "id INTEGER PRIMARY KEY, code TEXT (AFLM/AFLW/VFL/VFLW), name TEXT",
      "seasons": "id INTEGER PRIMARY KEY, competition_id INTEGER REFERENCES competitions(id), year INTEGER, season_key TEXT (canonical selector, AFLW 2022-S6 or 2022-S7), display_name TEXT, is_complete INTEGER (0=in-progress, 1=all matches played)",
      "season_provider_ids": "season_id INTEGER, provider TEXT, provider_season_id TEXT. Verified provider season mappings.",
      "player_provider_ids": "provider TEXT, provider_id TEXT, player_id INTEGER, evidence_json TEXT. Provider identity crosswalk; names are not identity evidence.",
      "player_id_redirects": "retired_id INTEGER, canonical_id INTEGER, manifest_digest TEXT. Resolve retired internal IDs without altering issued predictions.",
      "teams": "id INTEGER PRIMARY KEY, name TEXT, abbreviation TEXT, competition_id INTEGER REFERENCES competitions(id)",
      "venues": "id INTEGER PRIMARY KEY, name TEXT, latitude REAL, longitude REAL, timezone TEXT (IANA, e.g. Australia/Melbourne), roof TEXT ('retractable' | 'none'), canonical_venue_id INTEGER REFERENCES venues(id) (alias -> physical ground; self when canonical)",
      "players": "id INTEGER PRIMARY KEY, first_name TEXT, surname TEXT, external_id TEXT, external_afl_player_id TEXT, date_of_birth TEXT, height_cm INTEGER, weight_kg INTEGER, is_retired INTEGER (NULL=unknown; source-verified 0/1 only), legacy_is_retired INTEGER (unverified imported/defaulted flag; never infer current availability)",
      "matches": "id INTEGER PRIMARY KEY, season_id INTEGER REFERENCES seasons(id), round TEXT, round_abbreviation TEXT, round_number INTEGER, round_type TEXT, date TEXT, local_time TEXT, kickoff_at TEXT (nullable canonical UTC source instant), lineups_observed_at TEXT (nullable UTC lineup observation), venue_id INTEGER REFERENCES venues(id), home_team_id INTEGER REFERENCES teams(id), away_team_id INTEGER REFERENCES teams(id), home_goals INTEGER, home_behinds INTEGER, home_points INTEGER, away_goals INTEGER, away_behinds INTEGER, away_points INTEGER, margin INTEGER, attendance INTEGER, external_afltables_id TEXT, external_fryzigg_id TEXT, external_afl_id TEXT, home_rushed_behinds INTEGER, away_rushed_behinds INTEGER, home_minutes_in_front INTEGER, away_minutes_in_front INTEGER, home_q1_goals INTEGER, home_q1_behinds INTEGER, home_q2_goals INTEGER, home_q2_behinds INTEGER, home_q3_goals INTEGER, home_q3_behinds INTEGER, home_q4_goals INTEGER, home_q4_behinds INTEGER, away_q1_goals INTEGER, away_q1_behinds INTEGER, away_q2_goals INTEGER, away_q2_behinds INTEGER, away_q3_goals INTEGER, away_q3_behinds INTEGER, away_q4_goals INTEGER, away_q4_behinds INTEGER, status TEXT, live_period_status TEXT, completed_quarter INTEGER (NULL or 0-4; highest fully completed quarter)",
      "player_match_stats": "id INTEGER PRIMARY KEY, match_id INTEGER REFERENCES matches(id), player_id INTEGER REFERENCES players(id), team_id INTEGER REFERENCES teams(id), guernsey_number INTEGER, player_position TEXT, subbed TEXT, time_on_ground_pct REAL, kicks INTEGER, handballs INTEGER, disposals INTEGER, effective_disposals INTEGER, disposal_efficiency_pct REAL, marks INTEGER, bounces INTEGER, tackles INTEGER, one_percenters INTEGER, clangers INTEGER, contested_possessions INTEGER, uncontested_possessions INTEGER, goals INTEGER, behinds INTEGER, goal_assists INTEGER, shots_at_goal INTEGER, score_involvements INTEGER, score_launches INTEGER, centre_clearances INTEGER, stoppage_clearances INTEGER, clearances INTEGER, contested_marks INTEGER, marks_inside_fifty INTEGER, intercept_marks INTEGER, marks_on_lead INTEGER, free_kicks_for INTEGER, free_kicks_against INTEGER, hitouts INTEGER, hitouts_to_advantage INTEGER, hitout_win_pct REAL, ruck_contests INTEGER, inside_fifties INTEGER, rebounds INTEGER, turnovers INTEGER, intercepts INTEGER, metres_gained INTEGER, pressure_acts INTEGER, def_half_pressure_acts INTEGER, tackles_inside_fifty INTEGER, spoils INTEGER, contest_def_losses INTEGER, contest_def_one_on_ones INTEGER, contest_off_one_on_ones INTEGER, contest_off_wins INTEGER, effective_kicks INTEGER, ground_ball_gets INTEGER, f50_ground_ball_gets INTEGER, brownlow_votes INTEGER, rating_points REAL, afl_fantasy_score INTEGER, supercoach_score INTEGER, goal_accuracy REAL, goal_efficiency REAL, shot_efficiency REAL, kick_efficiency REAL, kick_to_handball_ratio REAL, contested_possession_rate REAL, contest_def_loss_pct REAL, contest_off_wins_pct REAL, centre_bounce_attendances INTEGER, kickins INTEGER, kickins_playon INTEGER, interchange_counts INTEGER, total_possessions INTEGER",
      "player_season_pav": "id INTEGER PRIMARY KEY, player_id INTEGER REFERENCES players(id), season_id INTEGER REFERENCES seasons(id), team_id INTEGER REFERENCES teams(id), off_pav REAL, mid_pav REAL, def_pav REAL, total_pav REAL",
      "match_lineups": "id INTEGER PRIMARY KEY, match_id INTEGER REFERENCES matches(id), player_id INTEGER REFERENCES players(id), team_id INTEGER REFERENCES teams(id), guernsey_number INTEGER, position TEXT, is_emergency INTEGER (0=no, 1=yes), is_substitute INTEGER (0=no, 1=yes)",
      "match_weather": "match_id INTEGER REFERENCES matches(id), kind TEXT ('observed' | 'forecast'), temp_c REAL (deg C, mean over the 3h match window), precip_mm REAL (mm, total over the 3h match window), precip_24h_prior_mm REAL (mm, total over the 24h before the match window; ground condition), wind_speed_kmh REAL (km/h, max over the 3h match window), wind_gust_kmh REAL (km/h, max over the 3h match window), humidity_pct REAL (%, mean over the 3h match window), source TEXT ('era5_land+era5' | 'historical_forecast' | 'best_match'), fetched_at TEXT (UTC ISO 8601), PRIMARY KEY (match_id, kind)",
      "match_predictions": "match_id INTEGER PRIMARY KEY REFERENCES matches(id), tipper_run_id INTEGER (nullable reference to prospective capture run), home_win_prob REAL (0..1, home team's win probability), predicted_margin REAL (points, one decimal; positive = home favoured), model_version TEXT (production model identity and full source revision), generated_at TEXT (UTC ISO 8601)",
      "coach_backfill_progress": "provider TEXT, season INTEGER, cursor TEXT, assignments_json TEXT, updated_at TEXT, PRIMARY KEY (provider, season)",
      "coaches": "id TEXT PRIMARY KEY, display_name TEXT, profile_url TEXT, created_at TEXT",
      "coach_external_ids": "provider TEXT, external_coach_id TEXT, coach_id TEXT REFERENCES coaches(id), display_name TEXT, profile_url TEXT, verified INTEGER, PRIMARY KEY (provider, external_coach_id)",
      "coach_external_match_ids": "provider TEXT, external_match_id TEXT, match_id INTEGER REFERENCES matches(id), PRIMARY KEY (provider, external_match_id)",
      "coach_observations": "id INTEGER PRIMARY KEY, provider TEXT, external_coach_id TEXT, external_match_id TEXT, coach_id TEXT, match_id INTEGER, team_id INTEGER, season INTEGER, source_url TEXT, retrieved_at TEXT, match_date TEXT, display_name TEXT, raw_team TEXT, home_points INTEGER, away_points INTEGER",
      "match_coaches": "match_id INTEGER REFERENCES matches(id), team_id INTEGER REFERENCES teams(id), coach_id TEXT REFERENCES coaches(id), observation_id INTEGER REFERENCES coach_observations(id), updated_at TEXT, PRIMARY KEY (match_id, team_id)",
      "coach_import_pages": "provider TEXT, season INTEGER, scope TEXT, status TEXT, last_checked_at TEXT, last_success_at TEXT, failure_count INTEGER",
      "coach_import_diagnostics": "id INTEGER PRIMARY KEY, provider TEXT, season INTEGER, scope TEXT, source_url TEXT, reason TEXT, created_at TEXT, resolved_at TEXT",
      "public_input_revision": "id INTEGER PRIMARY KEY CHECK (id = 1), revision INTEGER, in_progress INTEGER, write_started_at TEXT, write_holder TEXT (opaque operation ownership), write_operation TEXT (resumable operation identity)"
    },
    "notes": [
      "ALWAYS filter queries by competition. Join `seasons s ON m.season_id = s.id` then `competitions c ON s.competition_id = c.id` and add `WHERE c.code = ?`. Without this filter, results mix competitions silently — team rows with the same name (e.g. Carlton AFLM vs Carlton VFL) have distinct team_id values, so unfiltered aggregates double-count.",
      "Coverage expectations, exact ranges, sources, and review dates are canonical in database.coverage_contract. Descriptive notes never override that typed contract.",
      "match_coaches has at most one credited coach per match and participant club. It stores canonical AFL Tables assignments; LEFT JOIN it to preserve unknown assignments. Coach IDs use provider-qualified identity unless a cross-provider match has been explicitly verified.",
      "coach_observations retains AFL Tables and FootyWire evidence independently. FootyWire is comparison-only and never replaces the canonical AFL Tables assignment. Source disagreements remain queryable in this table.",
      "Historical AFLM team identities are Brisbane Bears through 1996, Fitzroy, and Brisbane Lions. Their distinct team IDs preserve the source history; downstream ELO systems may carry ratings across the Bears-to-Lions transition.",
      "public_input_revision is a monotonic input-change marker. It changes for meaningful match result or canonical coach changes. Read revision, in_progress, and write_started_at before and after a native snapshot; retry on a revision difference or any active write. A stale marker requires operator recovery after checking the shared lease and incomplete work. Last-check timestamps, secondary observations, diagnostics, and coverage checks do not change the revision.",
      "Round labels: matches has TWO round-string columns mirroring the AFL API directly (same approach as the R fitzRoy package — no cross-competition normalisation):",
      "- `round` is the long form: `Round 1`–`Round N`, `Opening Round` (AFLM 2024+, round_number=0), `Wildcard` (VFL only, before finals), and finals `Finals Week 1` / `Semi Finals` / `Preliminary Finals` / `Grand Final`. The AFLM 2026 finals format adds `Wildcard Finals` and `Qualifying & Elimination Finals`.",
      "- `round_abbreviation` is the AFL's short form: `Rd 1`–`Rd N`, `OR`, `WC`, `FW1`, `SF`, `PF`, `GF`. Finals round names without a mapped short form fall back to `F<round_number>` (e.g. AFLM 2026 `Wildcard Finals` = `F25`, `Qualifying & Elimination Finals` = `F26`). Stable across all four competitions; useful for compact display and abbreviation-based filters.",
      "- `round_number` is a per-season ordinal: continuous through regular and finals (e.g. AFLM 2024 finals are 25–28; AFLW 2025 finals are 13–16; VFL 2025 has Wildcard at 22 then finals 23–26). Round numbers don't align across competitions — AFLM R1 is March, AFLW R1 is August, VFL R1 is April.",
      "- `round_type` is `Regular` (home-and-away + Opening Round + Wildcard) or `Finals`.",
      "Pre-v3.0.0 historical data may still have legacy `EF`/`QF`/`SF`/`PF`/`GF` strings in `round` for AFLM finals 2012–2025; these get rewritten to the long form on the next backfill.",
      "round_type is either 'Regular' or 'Finals'. For granular finals identification use the round column.",
      "Opening Round (round_number=0, only present for AFLM 2024+) is played before Round 1 and must not be excluded from queries.",
      "AFLM 2012–2025 finals labels were rewritten in v3.0.0 to match fitzroy v2.1's labels; legacy `EF/QF/SF/PF/GF` no longer appears in the data.",
      "Players have no team_id column — a player's team is determined per-game via player_match_stats.team_id. The same player_id can appear in multiple competitions in the same season (e.g. an AFLM-listed reserves player who also plays VFL games for the affiliate); resolve their competition per stat row via match → season → competition.",
      "total_pav ≈ off_pav + mid_pav + def_pav. ~12-15% of rows differ by exactly ±0.01 because each component is rounded independently. Treat the relationship as approximate, not exact.",
      "PAV zone meanings: off_pav = offensive (goals, score involvements, forward craft); mid_pav = midfield (disposals, clearances, tackles, contested ball); def_pav = defensive (intercepts, spoils, one-percenters, rebounds).",
      "PAV interpretation (AFLM scale): 25+ exceptional (Brownlow contention), 20-25 great (All-Australian), 15-20 very good (team best-22), 10-15 solid contributor, 5-10 below average or limited games, <5 minimal contribution. AFLW PAV is on a similar but lower-totals scale because of shorter games and smaller squads.",
      "Use LEFT JOIN when combining player_season_pav with player_match_stats because PAV is not applicable to every competition-season.",
      "match date format is ISO 8601 (YYYY-MM-DD).",
      "matches.margin is signed from the home team's perspective: positive = home team won by that many points, negative = away team won. Use ABS(margin) for absolute margin.",
      "teams.abbreviation: AFL standard 2–4 letter codes for AFLM (ADE, BL, CARL, COLL, ESS, FITZ, FREO, GEEL, GCFC, GWS, HAW, MELB, NM, PORT, RICH, STK, SYD, WCE, WB). May be NULL for AFLW/VFL/VFLW teams sourced from fitzroy.",
      "external_afl_player_id is the AFL API player ID (CD_I format).",
      "metres_gained can be negative (valid — player lost net territory). Minimum observed: -92.",
      "subbed values are 'Not Subbed' and 'Subbed'.",
      "local_time is Melbourne local time (AEST/AEDT) as HH:MM:SS for every competition; venue-native time is intentionally not stored.",
      "matches.status lifecycle values are 'Upcoming', 'Live', 'Complete', 'Postponed', and 'Cancelled'. Populated for every row: historical played matches are 'Complete', and the 38 unscored VFL/VFLW 2021 COVID-era matches are 'Cancelled' (NULL scores there mean cancelled, not missing data).",
      "matches.live_period_status is opaque raw AFL API text; observed values include 'LIVE', 'QTR_TIME', 'HALF_TIME', '3QTR_TIME', and 'FULL_TIME'.",
      "matches.completed_quarter is the highest fully completed quarter from the AFL API match clock: 0 means play has not completed a quarter, 1-4 identify the last completed quarter, and NULL means no clock was supplied or the row predates refresh. Pair it with status; it is five-minute-sync context, not a live siren SLA.",
      "match_weather: up to two rows per match, keyed (match_id, kind). kind='forecast' is the pre-match Open-Meteo forecast, overwritten in place per refresh and KEPT after the match (compare with observed for forecast error); kind='observed' is the post-match value.",
      "match_weather window: metrics cover the 3h from scheduled start — temp_c/humidity_pct are means, precip_mm a total, wind_speed_kmh/wind_gust_kmh maxima. precip_24h_prior_mm is rainfall in the 24h BEFORE the window (ground condition, separate from in-game rain).",
      "match_weather.source: 'era5_land+era5' = final reanalysis (temp/humidity/wind from ERA5-Land, precipitation from ERA5); 'historical_forecast' = interim observed value, upgraded to reanalysis within ~a week; 'best_match' = forecast rows. Data from Open-Meteo (CC-BY 4.0).",
      "Venue aliases: sponsor renames create separate venues rows; venues.canonical_venue_id points to the physical ground — self for canonical rows, NULL for venues the sync has inserted but not yet classified. Group by physical venue via JOIN venues cv ON cv.id = COALESCE(v.canonical_venue_id, v.id) (the COALESCE covers the unclassified-NULL case).",
      "venues.roof = 'retractable' (Marvel Stadium only) flags grounds where rain may never reach the surface; match_weather always stores ambient conditions, so discount them yourself for roofed venues. Cancelled matches and the 'To Be Confirmed' placeholder venue (id 17748, NULL geodata) never get match_weather rows.",
      "match_predictions retains one stored row per match, combining chronological historical season backfill with real-time Tipper predictions. Read both together for season performance. home_win_prob (0..1) and predicted_margin (one decimal, positive = home favoured) use the HOME team's perspective; model_version records production model identity and full source revision. generated_at is the actual generation time; tipper_run_id is optional and NULL for backfilled rows. Use LEFT JOIN to report missing predictions.",
      "For tipping_performance, infer the tipped winner from home_win_prob >= 0.5 (home) or < 0.5 (away), not rounded predicted_margin. Accuracy excludes draws; draws and decisive_matches count predicted games. Margin MAE includes covered draws. through_date is the latest scored prediction date.",
      "match_lineups represents the post-change team — the players who actually took the field. Treat absence as not-yet-published rather than canonical.",
      "match_lineups is_emergency=1 means the player is named as an emergency and may not play.",
      "match_lineups is_substitute=1 marks all interchange/bench players (INT + SUB positions), not just the medical sub. To find just the medical substitute, filter on position = 'SUB'.",
      "match_lineups position codes: 18 starting positions (FB, BPL, BPR, CHB, HBFL, HBFR, FF, FPL, FPR, CHF, HFFL, HFFR, C, WL, WR, R, RR, RK), plus INT (interchange), SUB (medical substitute), and EMERG (emergency).",
      "Most players with both fryzigg and AFL API data are unified under a single player_id. A small number of common-name players may have separate records for genuinely different people who share a name.",
      "Integrity-check views (v_integrity_disposals, v_integrity_match_points, v_integrity_quarter_scores, v_integrity_margin, v_integrity_brownlow) return one row per invariant violation; an empty result set means the invariant holds.",
      "seasons.is_complete: 1 when every match in the season has been played (home_points NOT NULL for all rows). 0 for in-progress and not-started seasons."
    ],
    "common_joins": {
      "multi_comp_summary": "-- Per-competition match counts for a season\nSELECT c.code AS competition, COUNT(m.id) AS matches\nFROM competitions c\nJOIN seasons s ON s.competition_id = c.id\nJOIN matches m ON m.season_id = s.id\nWHERE s.season_key = ?\nGROUP BY c.code\nORDER BY c.code",
      "team_roster_pav": "-- Bind: competition, team name, canonical season key\nSELECT p.first_name, p.surname, psp.off_pav, psp.mid_pav, psp.def_pav, psp.total_pav\nFROM player_season_pav psp\nJOIN players p ON psp.player_id = p.id\nJOIN seasons s ON psp.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams t ON psp.team_id = t.id\nWHERE c.code = ? AND t.name = ? AND s.season_key = ?\nORDER BY psp.total_pav DESC",
      "player_career_arc": "-- Bind: competition, player_id\nSELECT s.year, SUM(pms.disposals) as total_disposals, SUM(pms.goals) as total_goals,\n  COUNT(*) as games, psp.total_pav, psp.off_pav, psp.mid_pav, psp.def_pav\nFROM player_match_stats pms\nJOIN matches m ON pms.match_id = m.id\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nLEFT JOIN player_season_pav psp ON psp.player_id = pms.player_id AND psp.season_id = s.id\nWHERE c.code = ? AND pms.player_id = ?\nGROUP BY s.year, psp.total_pav, psp.off_pav, psp.mid_pav, psp.def_pav\nORDER BY s.year",
      "zone_leaders": "-- Bind: competition, canonical season key\nSELECT p.first_name, p.surname, t.name as team, psp.mid_pav, psp.off_pav, psp.def_pav, psp.total_pav\nFROM player_season_pav psp\nJOIN players p ON psp.player_id = p.id\nJOIN seasons s ON psp.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams t ON psp.team_id = t.id\nWHERE c.code = ? AND s.season_key = ?\nORDER BY psp.total_pav DESC\nLIMIT 20",
      "match_with_teams_venue": "-- Bind: competition, canonical season key\nSELECT m.date, m.round, ht.name as home_team, at.name as away_team,\n  m.home_points, m.away_points, m.margin, v.name as venue\nFROM matches m\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams ht ON m.home_team_id = ht.id\nJOIN teams at ON m.away_team_id = at.id\nJOIN venues v ON m.venue_id = v.id\nWHERE c.code = ? AND s.season_key = ?",
      "match_coaches_lookup": "-- Bind: competition, canonical season key\nSELECT m.id AS match_id, m.date, m.round, ht.name AS home_team, at.name AS away_team,\n  home_coach.display_name AS home_coach, away_coach.display_name AS away_coach,\n  home_coach.id AS home_coach_id, away_coach.id AS away_coach_id\nFROM matches m\nJOIN seasons s ON s.id = m.season_id\nJOIN competitions c ON c.id = s.competition_id\nJOIN teams ht ON ht.id = m.home_team_id\nJOIN teams at ON at.id = m.away_team_id\nLEFT JOIN match_coaches hm ON hm.match_id = m.id AND hm.team_id = m.home_team_id\nLEFT JOIN coaches home_coach ON home_coach.id = hm.coach_id\nLEFT JOIN match_coaches am ON am.match_id = m.id AND am.team_id = m.away_team_id\nLEFT JOIN coaches away_coach ON away_coach.id = am.coach_id\nWHERE c.code = ? AND s.season_key = ?\nORDER BY m.date, m.id",
      "coaching_source_comparisons": "-- AFL Tables vs FootyWire evidence for one AFLM season.\n-- Bind: canonical season key\nSELECT primary_obs.match_date, primary_obs.raw_team AS team,\n  primary_obs.display_name AS afl_tables_coach, secondary_obs.display_name AS footywire_coach,\n  primary_obs.source_url AS afl_tables_evidence, secondary_obs.source_url AS footywire_evidence\nFROM coach_observations primary_obs\nJOIN coach_observations secondary_obs ON secondary_obs.match_id = primary_obs.match_id\n  AND secondary_obs.team_id = primary_obs.team_id AND secondary_obs.provider = 'footywire'\nWHERE primary_obs.provider = 'afl-tables' AND primary_obs.season = ?\n  AND primary_obs.coach_id <> secondary_obs.coach_id\nORDER BY primary_obs.match_date, team",
      "lineup_round_comparison": "-- Compare team lineups between two rounds (shows ins/outs)\n-- Bind: competition, team name, current round number, prev round number, then again for OUT half\nSELECT 'IN' as change, p.first_name, p.surname, ml.position\nFROM match_lineups ml\nJOIN matches m ON ml.match_id = m.id\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN players p ON ml.player_id = p.id\nJOIN teams t ON ml.team_id = t.id\nWHERE c.code = ? AND t.name = ? AND m.round_number = ? AND ml.is_emergency = 0\n  AND ml.player_id NOT IN (\n    SELECT ml2.player_id FROM match_lineups ml2\n    JOIN matches m2 ON ml2.match_id = m2.id\n    WHERE ml2.team_id = ml.team_id AND m2.round_number = ? AND m2.season_id = m.season_id AND ml2.is_emergency = 0\n  )\nUNION ALL\nSELECT 'OUT', p.first_name, p.surname, ml.position\nFROM match_lineups ml\nJOIN matches m ON ml.match_id = m.id\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN players p ON ml.player_id = p.id\nJOIN teams t ON ml.team_id = t.id\nWHERE c.code = ? AND t.name = ? AND m.round_number = ? AND ml.is_emergency = 0\n  AND ml.player_id NOT IN (\n    SELECT ml2.player_id FROM match_lineups ml2\n    JOIN matches m2 ON ml2.match_id = m2.id\n    WHERE ml2.team_id = ml.team_id AND m2.round_number = ? AND m2.season_id = m.season_id AND ml2.is_emergency = 0\n  )",
      "lineup_with_pav": "-- Team lineup enriched with PAV data\n-- Bind: competition, team name, round number, canonical season key\nSELECT p.first_name, p.surname, ml.position, ml.guernsey_number,\n  ml.is_emergency, ml.is_substitute,\n  psp.off_pav, psp.mid_pav, psp.def_pav, psp.total_pav\nFROM match_lineups ml\nJOIN matches m ON ml.match_id = m.id\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN players p ON ml.player_id = p.id\nJOIN teams t ON ml.team_id = t.id\nLEFT JOIN player_season_pav psp ON psp.player_id = p.id AND psp.season_id = s.id\nWHERE c.code = ? AND t.name = ? AND m.round_number = ? AND s.season_key = ?\nORDER BY ml.is_emergency, psp.total_pav DESC NULLS LAST",
      "match_weather_lookup": "-- Weather for one match (observed + retained forecast) via the canonical venue.\n-- Bind: competition, canonical season key, home team name\nSELECT m.date, m.round, ht.name AS home_team, at.name AS away_team,\n  cv.name AS venue, cv.roof, w.kind, w.source,\n  w.temp_c, w.precip_mm, w.precip_24h_prior_mm,\n  w.wind_speed_kmh, w.wind_gust_kmh, w.humidity_pct\nFROM matches m\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams ht ON m.home_team_id = ht.id\nJOIN teams at ON m.away_team_id = at.id\nJOIN venues v ON m.venue_id = v.id\nJOIN venues cv ON cv.id = COALESCE(v.canonical_venue_id, v.id)\nLEFT JOIN match_weather w ON w.match_id = m.id\nWHERE c.code = ? AND s.season_key = ? AND ht.name = ?\nORDER BY m.date, w.kind",
      "wet_game_scoring": "-- Scoring in wet games, excluding roofed venues.\n-- Bind: competition\nSELECT s.year, m.date, ht.name AS home_team, at.name AS away_team,\n  m.home_points + m.away_points AS total_points,\n  w.precip_mm, w.precip_24h_prior_mm\nFROM matches m\nJOIN match_weather w ON w.match_id = m.id AND w.kind = 'observed'\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams ht ON m.home_team_id = ht.id\nJOIN teams at ON m.away_team_id = at.id\nJOIN venues v ON m.venue_id = v.id\nJOIN venues cv ON cv.id = COALESCE(v.canonical_venue_id, v.id)\nWHERE c.code = ? AND m.home_points IS NOT NULL\n  AND w.precip_mm >= 2.0 AND cv.roof = 'none'\nORDER BY w.precip_mm DESC",
      "round_predictions": "-- Model predictions for a round, with team names.\n-- Bind: competition, canonical season key, round number\nSELECT m.date, m.round, ht.name AS home_team, at.name AS away_team,\n  mp.home_win_prob, mp.predicted_margin, mp.model_version\nFROM matches m\nJOIN seasons s ON m.season_id = s.id\nJOIN competitions c ON s.competition_id = c.id\nJOIN teams ht ON m.home_team_id = ht.id\nJOIN teams at ON m.away_team_id = at.id\nLEFT JOIN match_predictions mp ON mp.match_id = m.id\nWHERE c.code = ? AND s.season_key = ? AND m.round_number = ?\nORDER BY m.date",
      "tipping_performance": "-- Bind: competition, canonical season key. Includes retained backfill and real-time predictions.\nWITH summary AS (\n  SELECT c.code AS competition, s.year, COUNT(*) AS completed_matches,\n    COUNT(mp.match_id) AS predictions, COUNT(*) - COUNT(mp.match_id) AS missing_predictions,\n    SUM(CASE WHEN (mp.home_win_prob >= 0.5 AND m.home_points > m.away_points)\n      OR (mp.home_win_prob < 0.5 AND m.away_points > m.home_points) THEN 1 ELSE 0 END) AS correct_winners,\n    SUM(CASE WHEN mp.match_id IS NOT NULL AND m.home_points != m.away_points THEN 1 ELSE 0 END) AS decisive_matches,\n    SUM(CASE WHEN mp.match_id IS NOT NULL AND m.home_points = m.away_points THEN 1 ELSE 0 END) AS draws,\n    AVG(ABS(mp.predicted_margin - (m.home_points - m.away_points))) AS margin_mae,\n    MAX(CASE WHEN mp.match_id IS NOT NULL THEN m.date END) AS through_date\n  FROM matches m JOIN seasons s ON s.id = m.season_id\n  JOIN competitions c ON c.id = s.competition_id\n  LEFT JOIN match_predictions mp ON mp.match_id = m.id\n  WHERE c.code = ? AND s.season_key = ? AND m.status = 'Complete'\n    AND m.home_points >= 0 AND m.away_points >= 0\n  GROUP BY c.code, s.year\n) SELECT *, 100.0 * correct_winners / NULLIF(decisive_matches, 0) AS accuracy_pct FROM summary",
      "ladder": "-- Ladder for a season (regular season only). Works for any competition.\n-- Bind: competition, canonical season key\nSELECT t.name AS team,\n  COUNT(*) AS played,\n  SUM(CASE WHEN (m.home_team_id = t.id AND m.home_points > m.away_points) OR (m.away_team_id = t.id AND m.away_points > m.home_points) THEN 1 ELSE 0 END) AS wins,\n  SUM(CASE WHEN (m.home_team_id = t.id AND m.home_points < m.away_points) OR (m.away_team_id = t.id AND m.away_points < m.home_points) THEN 1 ELSE 0 END) AS losses,\n  SUM(CASE WHEN m.home_points = m.away_points THEN 1 ELSE 0 END) AS draws,\n  SUM(CASE WHEN m.home_team_id = t.id THEN m.home_points ELSE m.away_points END) AS points_for,\n  SUM(CASE WHEN m.home_team_id = t.id THEN m.away_points ELSE m.home_points END) AS points_against,\n  ROUND(100.0 * SUM(CASE WHEN m.home_team_id = t.id THEN m.home_points ELSE m.away_points END) / NULLIF(SUM(CASE WHEN m.home_team_id = t.id THEN m.away_points ELSE m.home_points END), 0), 1) AS percentage,\n  SUM(CASE WHEN (m.home_team_id = t.id AND m.home_points > m.away_points) OR (m.away_team_id = t.id AND m.away_points > m.home_points) THEN 4 WHEN m.home_points = m.away_points THEN 2 ELSE 0 END) AS premiership_points\nFROM teams t\nJOIN competitions c ON t.competition_id = c.id\nJOIN matches m ON t.id = m.home_team_id OR t.id = m.away_team_id\nJOIN seasons s ON m.season_id = s.id\nWHERE c.code = ? AND s.season_key = ? AND m.round_type = 'Regular' AND m.home_points IS NOT NULL\nGROUP BY t.id\nORDER BY premiership_points DESC, percentage DESC"
    }
